/// <reference types="../../types/react-table-config" />

import { ActionType, TableInstance, TableState } from 'react-table';
import type { Hooks, Column, MetaBase } from 'react-table';

import { useUserActionsActions } from './actions.js';
import {
  findDefaultActionColumn,
  prepareActionColumn,
  getUpdatedColumnsArray,
} from './components/RowActions.js';
import { UserActionConfig } from './useUserActions.types.js';

/** State reducer that triggers a re-render of the table when a columnPropertiesChanged action has been dispatched. */
function reducer(state: TableState, action: ActionType) {
  return action.type === useUserActionsActions.columnPropertiesChanged
    ? { ...state } // returning a shallow copy of the table state causes the entire table to re-render
    : state;
}

/** Disables the default sorting mechanism by setting `canSort` to `false` and setting a new property for the useUserActions plugin. */
function disableDefaultSorting(instance: TableInstance) {
  if (!instance.userActions) {
    return;
  }

  const { defaultColumnActionProvider, columnActionProviders } =
    instance.userActions as UserActionConfig;

  for (const column of instance.allColumns) {
    if (
      defaultColumnActionProvider !== null ||
      columnActionProviders[`${column.id}`] !== undefined
    ) {
      column.canSortViaUserAction = column.canSort ?? false;
      column.canSort = false;
    }
  }
}

/** Table hook that enables user actions for cells and rows. */
export function useUserActions(hooks: Hooks): void {
  hooks.columns.push(enableRowAction);
  hooks.stateReducers.push(reducer);
  // Note: we *need* to mutate the final instance,
  // otherwise the other plugins will not have their props set
  hooks.useFinalInstance.push(disableDefaultSorting);
}

// eslint-disable-next-line @typescript-eslint/ban-types
function enableRowAction<D extends {}>(
  columns: Column<D>[],
  { instance }: MetaBase<D>,
): Column<D>[] {
  const { rowActionsProvider } = instance.userActions as UserActionConfig;
  if (typeof rowActionsProvider === 'function') {
    const [defaultCol, defaultColIndex] = findDefaultActionColumn(
      columns as Column<any>[], // eslint-disable-line @typescript-eslint/no-explicit-any
    );

    const actionColumn = prepareActionColumn(
      rowActionsProvider,
      defaultCol,
    ) as Column<D>;
    return getUpdatedColumnsArray(
      columns as Column<any>[], // eslint-disable-line @typescript-eslint/no-explicit-any
      actionColumn as Column<any>, // eslint-disable-line @typescript-eslint/no-explicit-any
      defaultColIndex,
    ) as Column<D>[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  }
  return columns;
}

useUserActions.pluginName = 'useUserActions';
